 const body=sec.querySelector('tbody');
 function paint(g){const list=g==='ALL'?DATA:DATA.filter(x=>x.g===g);body.innerHTML=list.map(x=>'<tr><td>'+x.g+'</td><td><b>'+x.c+'</b></td><td>'+x.n+'</td><td>'+fmt(x.b)+'</td><td class="'+(parseFloat(x.d)>=0?'var-up':'var-down')+'">'+(parseFloat(x.d)>0?'+':'')+x.d+'</td><td>'+pct(x.cum)+'</td><td>'+pct(x.ann)+'</td><td>'+pct(x.m1)+'</td><td>'+pct(x.m3)+'</td><td>'+pct(x.m6)+'</td><td>'+pct(x.y1)+'</td><td>'+pct(x.y3)+'</td><td>'+pct(x.y5)+'</td><td>'+fmt(x.a)+'</td></tr>').join('')}
 sec.querySelectorAll('.var-tab').forEach(b=>b.onclick=()=>{sec.querySelectorAll('.var-tab').forEach(x=>x.classList.remove('on'));b.classList.add('on');paint(b.dataset.g)});paint('ALL');
 const old=document.getElementById('annualTop10'); if(old)old.style.display='none';
